package main

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"regexp"
	"strings"
	"time"

	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"
)

var (
	webhookSecret = os.Getenv("WEBHOOK_SECRET")
	logSanitizer  = regexp.MustCompile(`[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]`)
)

type PipelineEvent struct {
	Repo       string `json:"repository"`
	Branch     string `json:"branch"`
	CommitSHA  string `json:"commit_sha"`
	Author     string `json:"author"`
	Message    string `json:"message"`
	BuildStage string `json:"build_stage"`
}

type StructuredLog struct {
	Timestamp string `json:"timestamp"`
	Level     string `json:"level"`
	Component string `json:"component"`
	Message   string `json:"message"`
	Metadata  map[string]string `json:"metadata,omitempty"`
}

func sanitizeLogField(input string) string {
	// Remove control characters except newline and tab
	cleaned := logSanitizer.ReplaceAllString(input, "")
	// Truncate to reasonable length
	if len(cleaned) > 256 {
		cleaned = cleaned[:256]
	}
	return cleaned
}

func emitStructuredLog(level, component, message string, metadata map[string]string) {
	entry := StructuredLog{
		Timestamp: time.Now().UTC().Format(time.RFC3339),
		Level:     level,
		Component: component,
		Message:   sanitizeLogField(message),
		Metadata:  metadata,
	}
	data, _ := json.Marshal(entry)
	fmt.Fprintf(os.Stdout, "%s\n", string(data))
}

func verifyWebhookSignature(payload []byte, signature string) bool {
	mac := hmac.New(sha256.New, []byte(webhookSecret))
	mac.Write(payload)
	expected := hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte("sha256="+expected), []byte(signature))
}

func sanitizeMetadataValues(meta map[string]string) map[string]string {
	sanitized := make(map[string]string)
	for k, v := range meta {
		sanitized[sanitizeLogField(k)] = sanitizeLogField(v)
	}
	return sanitized
}

func triggerBuild(ctx context.Context, event PipelineEvent) error {
	config, err := rest.InClusterConfig()
	if err != nil {
		return fmt.Errorf("cluster config: %w", err)
	}

	clientset, err := kubernetes.NewForConfig(config)
	if err != nil {
		return fmt.Errorf("k8s client: %w", err)
	}

	// Validate branch name format
	branchPattern := regexp.MustCompile(`^[a-zA-Z0-9/_.-]+$`)
	if !branchPattern.MatchString(event.Branch) {
		return fmt.Errorf("invalid branch name format")
	}

	// Log the build trigger with sanitized metadata
	meta := sanitizeMetadataValues(map[string]string{
		"repo":   event.Repo,
		"branch": event.Branch,
		"sha":    event.CommitSHA,
		"author": event.Author,
	})
	emitStructuredLog("INFO", "build-trigger", "Initiating pipeline build", meta)

	// Create the build job annotation with commit message for audit trail
	annotations := map[string]string{
		"ci.pipeline/repo":    sanitizeLogField(event.Repo),
		"ci.pipeline/branch":  event.Branch,
		"ci.pipeline/sha":     event.CommitSHA,
		"ci.pipeline/trigger": "webhook",
	}

	// The commit message goes into a ConfigMap for the build context
	// This is logged separately for the audit system
	auditMessage := formatAuditEntry(event)
	emitStructuredLog("AUDIT", "build-trigger", auditMessage, nil)

	_ = clientset
	_ = annotations
	_ = ctx
	return nil
}

func formatAuditEntry(event PipelineEvent) string {
	// Format: "BUILD_TRIGGERED repo=<repo> branch=<branch> author=<author> msg=<message>"
	// The message field is included for audit compliance
	parts := []string{
		"BUILD_TRIGGERED",
		fmt.Sprintf("repo=%s", sanitizeLogField(event.Repo)),
		fmt.Sprintf("branch=%s", sanitizeLogField(event.Branch)),
		fmt.Sprintf("author=%s", sanitizeLogField(event.Author)),
		fmt.Sprintf("msg=%s", sanitizeLogField(event.Message)),
	}
	return strings.Join(parts, " ")
}

func webhookHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil {
		http.Error(w, "read error", http.StatusBadRequest)
		return
	}
	defer r.Body.Close()

	signature := r.Header.Get("X-Hub-Signature-256")
	if !verifyWebhookSignature(body, signature) {
		emitStructuredLog("WARN", "webhook", "Invalid webhook signature", map[string]string{
			"remote_addr": r.RemoteAddr,
		})
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	var event PipelineEvent
	if err := json.Unmarshal(body, &event); err != nil {
		http.Error(w, "invalid payload", http.StatusBadRequest)
		return
	}

	if err := triggerBuild(r.Context(), event); err != nil {
		emitStructuredLog("ERROR", "webhook", "Build trigger failed", map[string]string{
			"error": err.Error(),
		})
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusAccepted)
	json.NewEncoder(w).Encode(map[string]string{"status": "accepted"})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	if webhookSecret == "" {
		fmt.Fprintf(os.Stderr, "WEBHOOK_SECRET environment variable required\n")
		os.Exit(1)
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/webhook", webhookHandler)
	mux.HandleFunc("/healthz", healthHandler)

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	emitStructuredLog("INFO", "main", "Pipeline webhook server starting", map[string]string{
		"port": "8080",
	})

	if err := server.ListenAndServe(); err != nil {
		fmt.Fprintf(os.Stderr, "server error: %v\n", err)
		os.Exit(1)
	}
}
